"149 :     public CommandLine parse(Options options, String[] arguments, 
150 :                              Properties properties, boolean stopAtNonOption)
151 :         throws ParseException
152 :     {
153 :         // clear out the data in options in case it's been used before (CLI-71)
154 :         for (Iterator it = options.helpOptions().iterator(); it.hasNext();) {
155 :             Option opt = (Option) it.next();
156 :             opt.clearValues();
157 :         }
158 : 
159 :         // initialise members
160 :         setOptions(options);
161 : 
162 :         cmd = new CommandLine();
163 : 
164 :         boolean eatTheRest = false;
165 : 
166 :         if (arguments == null)
167 :         {
168 :             arguments = new String[0];
169 :         }
170 : 
171 :         List tokenList = Arrays.asList(flatten(getOptions(), 
172 :                                                arguments, 
173 :                                                stopAtNonOption));
174 : 
175 :         ListIterator iterator = tokenList.listIterator();
176 : 
177 :         // process each flattened token
178 :         while (iterator.hasNext())
179 :         {
180 :             String t = (String) iterator.next();
181 : 
182 :             // the value is the double-dash
183 :             if ("--".equals(t))
184 :             {
185 :                 eatTheRest = true;
186 :             }
187 : 
188 :             // the value is a single dash
189 :             else if ("-".equals(t))
190 :             {
191 :                 if (stopAtNonOption)
192 :                 {
193 :                     eatTheRest = true;
194 :                 }
195 :                 else
196 :                 {
197 :                     cmd.addArg(t);
198 :                 }
199 :             }
200 : 
201 :             // the value is an option
202 :             else if (t.startsWith("-"))
203 :             {
204 :                 if (stopAtNonOption && !getOptions().hasOption(t))
205 :                 {
206 :                     eatTheRest = true;
207 :                     cmd.addArg(t);
208 :                 }
209 :                 else
210 :                 {
211 :                     processOption(t, iterator);
212 :                 }
213 :             }
214 : 
215 :             // the value is an argument
216 :             else
217 :             {
218 :                 cmd.addArg(t);
219 : 
220 :                 if (stopAtNonOption)
221 :                 {
222 :                     eatTheRest = true;
223 :                 }
224 :             }
225 : 
226 :             // eat the remaining tokens
227 :             if (eatTheRest)
228 :             {
229 :                 while (iterator.hasNext())
230 :                 {
231 :                     String str = (String) iterator.next();
232 : 
233 :                     // ensure only one double-dash is added
234 :                     if (!"--".equals(str))
235 :                     {
236 :                         cmd.addArg(str);
237 :                     }
238 :                 }
239 :             }
240 :         }
241 : 
242 :         processProperties(properties);
243 :         checkRequiredOptions();
244 : 
245 :         return cmd;
246 :     }"

